	ios::sync_with_stdio(false);
	cin>>n>>m>>q;
	fr1(i,1,n){
		cin>>a[i];
		T1.val[i]=a[i];
	}
	fr1(i,1,m){
		cin>>b[i];
		T2.val[i]=b[i];
	}
