#include <bits/stdc++.h>
using namespace std;
#define MAXN 100001
#define int long long

int n, m, q, l_1, r_1, l_2, r_2;
int ans, ans1, ans2, ans3, ans4, ans5, ans6;

struct Block{
	#define MAXM 331   
	int n, len, tot;
	int a[MAXN], bl[MAXN];
	int L[MAXM], R[MAXM];   
	int maxn[MAXM], minn[MAXM];   
	Block(int x){   
		n = x;
	}

	void init(){   
		len = sqrt(n);   
		tot = (n-1)/len+1;   
		R[0] = 0;
		for (int i(1); i<=tot; ++i){   
			L[i] = R[i-1] + 1;
			R[i] = i * len;
		}
		R[tot] = n;   

		for (int i(1); i<=tot; ++i){
			maxn[i] = LLONG_MIN;
			minn[i] = LLONG_MAX; 
			for (int j(L[i]); j<=R[i]; ++j){
				bl[j] = i;   
				maxn[i] = max(maxn[i], a[j]);
				minn[i] = min(minn[i], a[j]);
			}
		}
	}

	int gmin(int l, int r){
		int p(bl[l]), q(bl[r]), res(LLONG_MAX);
		if (p == q){   
			for (int i(l); i<=r; ++i) res = min(res, a[i]);
			return res;
		}

		for (int i(l); i<=R[p]; ++i) res = min(res, a[i]);   
		for (int i(p+1); i<q; ++i) res = min(res, minn[i]);   
		for (int i(L[q]); i<=r; ++i) res = min(res, a[i]);   
		return res;
	}

	int gmax(int l, int r){   
		int p(bl[l]), q(bl[r]), res(LLONG_MIN);
		if (p == q){
			for (int i(l); i<=r; ++i) res = max(res, a[i]);
			return res;
		}

		for (int i(l); i<=R[p]; ++i) res = max(res, a[i]);
		for (int i(p+1); i<q; ++i) res = max(res, maxn[i]);
		for (int i(L[q]); i<=r; ++i) res = max(res, a[i]);
		return res;
	}
};

int f(int x){   
	if (x >= 0) return ans6;
	return ans5;
}

signed main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
