    cin >> n >> m >> q;
    Block a(n), b(m), a2(n), a3(n);   
    for (int i(1); i<=n; ++i){
    	cin >> a.a[i];
    	a2.a[i] = a3.a[i] = a.a[i];
    	if (a.a[i] < 0) a3.a[i] = LLONG_MAX;   
    	else a2.a[i] = LLONG_MIN;
	}
	for (int i(1); i<=m; ++i) cin >> b.a[i];

	a.init();   
	b.init();
	a2.init();
	a3.init();

	while (q--){
		cin >> l_1 >> r_1 >> l_2 >> r_2;
		ans1 = a.gmax(l_1, r_1);   
		ans2 = a.gmin(l_1, r_1);
		ans3 = a2.gmax(l_1, r_1);
		ans4 = a3.gmin(l_1, r_1);
		ans5 = b.gmax(l_2, r_2);
		ans6 = b.gmin(l_2, r_2);

		ans = max(ans1 * f(ans1), ans2 * f(ans2));   
		if (ans3 != LLONG_MIN) ans = max(ans, ans3 * f(ans3));   
		if (ans4 != LLONG_MAX) ans = max(ans, ans4 * f(ans4));   

		cout << ans << '\n';
	}

    return 0;
